# ====================================================================# OSP9 — KMS CDH Push (GCS + optional API ingest)# One-shot: วางแล้วรันจบ# ====================================================================Write-Host "=== KMS CDH Snapshot Push ===" -ForegroundColor Cyan# ---------- CONFIG ----------# บัคเก็ตจริง (แก้ตรงนี้ได้ถ้าย้ายบัคเก็ต)$env:KMS_GCS_BUCKET = "kms-central-knowingmind-app"# เส้นทางพื้นฐานใน Vault$VAULT_ROOT = Join-Path $env:USERPROFILE "knowingmind-vault\KMS_CDH"$SNAP_DIR   = Join-Path $VAULT_ROOT   "snapshots"$REPORT_DIR = Join-Path $VAULT_ROOT   "reports"# ปลายทางใน GCS$DST_SNAP = "gs://$($env:KMS_GCS_BUCKET)/KMS_CDH/snapshots/"$DST_REPO = "gs://$($env:KMS_GCS_BUCKET)/KMS_CDH/reports/"# เส้นทาง API (ตั้งสอง env นี้ก่อนรัน ถ้าจะใช้ API)# $env:KMA_API_BASE = "https://<run-url>/api"     # ไม่ใส่สแลชท้ายก็ได้# $env:KMA_API_KEY  = "<secret>"                  # Bearer token/key$INGEST_PATH = "/api/cdh/ingest"                  # path ของ ingest ใน service# ---------- PREP ----------# ให้โฟลเดอร์ครบ$null = New-Item -ItemType Directory -Force -Path $SNAP_DIR,$REPORT_DIR -ErrorAction SilentlyContinue# ---------- VALIDATE JSON ----------$bad = @()Get-ChildItem -Path (Join-Path $SNAP_DIR "*.json") -ErrorAction SilentlyContinue | ForEach-Object {  try {    Get-Content $_.FullName -Raw | ConvertFrom-Json | Out-Null  } catch {    $bad += $_.Name  }}if($bad.Count -gt 0){  Write-Warning ("BAD JSON: " + ($bad -join ", "))}else{  Write-Host "√ JSON OK" -ForegroundColor Green}# ---------- UPLOAD TO GCS (via gcloud storage cp) ----------if([string]::IsNullOrWhiteSpace($env:KMS_GCS_BUCKET)){  throw "ยังไม่ได้ตั้งค่า KMS_GCS_BUCKET"}$uploadOk = $true# snapshots/*$snaps = Get-ChildItem -Path (Join-Path $SNAP_DIR "*.json") -ErrorAction SilentlyContinueforeach($f in $snaps){  gcloud storage cp $f.FullName $DST_SNAP --quiet  if(-not $?) { $uploadOk = $false; Write-Warning "อัปโหลด snapshot ล้มเหลว: $($f.Name)" }}# reports/kms_timeline_latest.*$reports = Get-ChildItem -Path (Join-Path $REPORT_DIR "kms_timeline_latest.*") -ErrorAction SilentlyContinueforeach($f in $reports){  gcloud storage cp $f.FullName $DST_REPO --quiet  if(-not $?) { $uploadOk = $false; Write-Warning "อัปโหลด report ล้มเหลว: $($f.Name)" }}if($uploadOk){  Write-Host "√ Upload GCS สำเร็จ" -ForegroundColor Green}else{  Write-Warning "บางไฟล์อัปโหลดไม่สำเร็จ — ตรวจดูคำเตือนด้านบน"}# ---------- OPTIONAL: API INGEST ----------if($env:KMA_API_BASE -and $env:KMA_API_KEY){  # สร้าง URL อย่างปลอดภัย (กันสแลชซ้ำ/ขาด)  $base = $env:KMA_API_BASE.TrimEnd('/')  $path = $INGEST_PATH  if(-not $path.StartsWith('/')){ $path = "/$path" }  $url  = "$base$path"  $payloadFile = Join-Path $SNAP_DIR "kms_tasks_latest.json"  if(-not (Test-Path $payloadFile)){    Write-Warning "ไม่พบ payload สำหรับ API: $payloadFile"  } else {    $payload = Get-Content $payloadFile -Raw    try{      $headers = @{ Authorization = "Bearer $env:KMA_API_KEY" }      $resp = Invoke-RestMethod -Uri $url -Method Post -Headers $headers `              -Body $payload -ContentType "application/json"      Write-Host "√ API Ingest สำเร็จ → $url" -ForegroundColor Green    } catch {      Write-Warning "API ingest ไม่สำเร็จ ($url) — $_"      Write-Host  "ℹ ยังสามารถใช้ข้อมูลจาก GCS ต่อได้ตามปกติ" -ForegroundColor Yellow    }  }}else{  Write-Host "ℹ ไม่ตั้งค่า KMA_API_BASE/KMA_API_KEY → ใช้ GCS อย่างเดียว" -ForegroundColor Yellow}Write-Host "=== เสร็จสิ้น ===" -ForegroundColor Cyan# ====================================================================